## Code Example

```javascript
// Pseudo-code for idempotent dedupe using tenantId + eventId in DynamoDB
async function handleEvent(event){
  const key = `${event.tenantId}:${event.eventId}`;
  const exists = await dynamo.get({Key: {id: key}}).promise();
  if(exists.Item) return; // idempotent path
  await dynamo.put({TableName:'TenantEvents',Item:{id:key, ...event}}).promise();
  // forward to Kinesis for downstream processing
}
```

